### **Full `JobContext` Implementation**
```csharp
using Logistix.Server.Infrastructure.Database.Entity.Domain.Base;
using Logistix.Server.Infrastructure.Database.Entity.Domain.Job;
using Microsoft.EntityFrameworkCore;

namespace Logistix.Server.Infrastructure.Database.Context.Domain.Job
{
    public partial class JobContext : DbContext
    {
        public JobContext(DbContextOptions<JobContext> options)
            : base(options)
        {
        }

        // Define DbSets for each concrete job entity
        public virtual DbSet<JobIncomingEntity> IncomingJobs { get; set; } = null!;
        public virtual DbSet<JobProcessingEntity> ProcessingJobs { get; set; } = null!;
        public virtual DbSet<JobInRouteEntity> InRouteJobs { get; set; } = null!;
        public virtual DbSet<JobCompleteEntity> CompleteJobs { get; set; } = null!;
        public virtual DbSet<JobArchivedEntity> ArchivedJobs { get; set; } = null!;
        public virtual DbSet<JobAbandonedEntity> AbandonedJobs { get; set; } = null!;

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            // Apply TPC Mapping - Each entity gets its own table with all base entity fields
            modelBuilder.Entity<JobIncomingEntity>().ToTable("Logistix_Jobs_Incoming").UseTpcMappingStrategy();
            modelBuilder.Entity<JobProcessingEntity>().ToTable("Logistix_Jobs_Processing").UseTpcMappingStrategy();
            modelBuilder.Entity<JobInRouteEntity>().ToTable("Logistix_Jobs_InRoute").UseTpcMappingStrategy();
            modelBuilder.Entity<JobCompleteEntity>().ToTable("Logistix_Jobs_Closed").UseTpcMappingStrategy();
            modelBuilder.Entity<JobArchivedEntity>().ToTable("Logistix_Jobs_Archived").UseTpcMappingStrategy();
            modelBuilder.Entity<JobAbandonedEntity>().ToTable("Logistix_Jobs_Abandoned").UseTpcMappingStrategy();

            // Apply index configuration for optimized queries
            ConfigureIndexes<JobIncomingEntity>(modelBuilder);
            ConfigureIndexes<JobProcessingEntity>(modelBuilder);
            ConfigureIndexes<JobInRouteEntity>(modelBuilder);
            ConfigureIndexes<JobCompleteEntity>(modelBuilder);
            ConfigureIndexes<JobArchivedEntity>(modelBuilder);
            ConfigureIndexes<JobAbandonedEntity>(modelBuilder);
        }

        /// <summary>
        /// Configures indexes for job tables to optimize queries.
        /// </summary>
        private void ConfigureIndexes<TEntity>(ModelBuilder modelBuilder) where TEntity : JobBaseEntity
        {
            modelBuilder.Entity<TEntity>()
                .HasIndex(e => e.RecordGUID)
                .HasDatabaseName("IX_JobGUID")
                .IsUnique();

            modelBuilder.Entity<TEntity>()
                .HasIndex(e => e.DateCreated)
                .HasDatabaseName("IX_DateCreated");
        }
    }
}
```

---

### **Key Features of This Implementation**
1. **Ensures Table Per Concrete Type (TPC) Mapping**
   - Each **job state table** (`Logistix_Jobs_Incoming`, `Logistix_Jobs_Processing`, etc.) contains **all fields from `JobBaseEntity`**.
   - The `JobBaseEntity` **does not** generate a separate table.

2. **Abstract Base Entity (`JobBaseEntity`)**
   - This ensures that `JobBaseEntity` **cannot be instantiated directly** and **prevents EF Core from creating a base table**.

3. **Optimized Indexing**
   - `RecordGUID` is **indexed uniquely** for fast lookups.
   - `DateCreated` is **indexed** to improve sorting and filtering performance.
   - The `ConfigureIndexes<TEntity>()` method **reduces duplication** in the `OnModelCreating` method.

---

### **Expected Behavior**
- **Each job state (`JobIncomingEntity`, `JobProcessingEntity`, etc.) has its own table**.
- **All properties from `JobBaseEntity` are copied into each table**.
- **No foreign key relationships** are created between the tables.
- **Queries on `JobBaseEntity` will not work** (as expected with TPC).
- **Queries must be made directly on each job entity**.

---

### **Migration and Deployment**
To apply these changes, run:
```sh
dotnet ef migrations add ConvertToTPC
dotnet ef database update
```

