```csharp
using System;
using System.Security.Cryptography;
using System.Text;

class Program
{
    static void Main()
    {
        string password = "password";
        byte[] salt = Convert.FromBase64String("XohImNOsCzWj/ZqZQWvSaA==");

        // Compute PBKDF2 Hash
        byte[] hash = GeneratePBKDF2Hash(password, salt);

        // Convert to Base64 for easy comparison
        string hashBase64 = Convert.ToBase64String(hash);
        Console.WriteLine($"Computed Hash (Base64): {hashBase64}");

        // Expected hash for comparison
        string expectedHash = "y41AeU3tQm1Tf4IXHVd3DaXT1cfV27O5Bf5yydkrFBo=";
        Console.WriteLine($"Expected Hash: {expectedHash}");

        // Check if they match
