    }

    static byte[] GeneratePBKDF2Hash(string password, byte[] salt)
    {
        using var pbkdf2 = new Rfc2898DeriveBytes(password, salt, 100000, HashAlgorithmName.SHA256);
        return pbkdf2.GetBytes(32); // 32-byte (256-bit) hash
    }
}
