#### **Custom Hasher**
```csharp
using System;
using System.Security.Cryptography;
using Microsoft.AspNetCore.Identity;

public class CustomPasswordHasher : IPasswordHasher<UserEntity>
{
    private const int SaltSize = 16; // 16-byte salt
    private const int HashSize = 32; // 32-byte hash
    private const int Iterations = 100000;

    public string HashPassword(UserEntity user, string password)
    {
        byte[] salt = RandomNumberGenerator.GetBytes(SaltSize);
        using var pbkdf2 = new Rfc2898DeriveBytes(password, salt, Iterations, HashAlgorithmName.SHA256);
        byte[] hash = pbkdf2.GetBytes(HashSize);

        // Store salt + hash in Base64 format
        byte[] hashBytes = new byte[SaltSize + HashSize];
        Buffer.BlockCopy(salt, 0, hashBytes, 0, SaltSize);
        Buffer.BlockCopy(hash, 0, hashBytes, SaltSize, HashSize);

        return Convert.ToBase64String(hashBytes);
    }

    public PasswordVerificationResult VerifyHashedPassword(UserEntity user, string hashedPassword, string providedPassword)
    {
        byte[] hashBytes = Convert.FromBase64String(hashedPassword);

        byte[] salt = new byte[SaltSize];
        byte[] storedHash = new byte[HashSize];

        Buffer.BlockCopy(hashBytes, 0, salt, 0, SaltSize);
        Buffer.BlockCopy(hashBytes, SaltSize, storedHash, 0, HashSize);

        using var pbkdf2 = new Rfc2898DeriveBytes(providedPassword, salt, Iterations, HashAlgorithmName.SHA256);
        byte[] computedHash = pbkdf2.GetBytes(HashSize);

        return CryptographicOperations.FixedTimeEquals(computedHash, storedHash)
            ? PasswordVerificationResult.Success
            : PasswordVerificationResult.Failed;
    }
}
```

