#### **Updated `UserAccountContext`**
```csharp
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using System;

public class UserAccountContext : IdentityDbContext<UserEntity, IdentityRole<Guid>, Guid>
{
    public UserAccountContext(DbContextOptions<UserAccountContext> options)
        : base(options) { }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder); // Calls IdentityDbContext’s default configuration

        modelBuilder.Entity<UserEntity>().ToTable("Users");
        modelBuilder.Entity<IdentityRole<Guid>>().ToTable("Roles");
        modelBuilder.Entity<IdentityUserRole<Guid>>().ToTable("UserRoles");
        modelBuilder.Entity<IdentityUserClaim<Guid>>().ToTable("UserClaims");
        modelBuilder.Entity<IdentityUserLogin<Guid>>().ToTable("UserLogins");
        modelBuilder.Entity<IdentityRoleClaim<Guid>>().ToTable("RoleClaims");
        modelBuilder.Entity<IdentityUserToken<Guid>>().ToTable("UserTokens");

        // Apply Indexes for Performance
        modelBuilder.Entity<UserEntity>()
            .HasIndex(e => e.UserName)
            .HasDatabaseName("IX_UserName")
            .IsUnique();

        modelBuilder.Entity<UserEntity>()
            .HasIndex(e => e.Email)
            .HasDatabaseName("IX_Email")
            .IsUnique();
    }
}
```
✅ **Now Identity’s built-in tables will be used** (`Users`, `Roles`, `UserRoles`, `Tokens`, etc.).

