    using Microsoft.AspNetCore.Identity;
    using Microsoft.Extensions.DependencyInjection;
    using System;
    using System.Threading.Tasks;
    using Logistix.Server.Infrastructure.Database.Entity.Infrastructure.User;

    public static class UserSeeder
    {
        public static async Task SeedAdminUserAsync(IServiceProvider services)
        {
            using var scope = services.CreateScope();
            var userManager = scope.ServiceProvider.GetRequiredService<UserManager<UserEntity>>();
            var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole<Guid>>>();

            string adminEmail = "admin@example.com";
            string adminPassword = "P@ssw0rd!"; // 🔹 Change this securely
            string adminRole = "Admin";

            // Ensure the role exists
            if (!await roleManager.RoleExistsAsync(adminRole))
            {
                await roleManager.CreateAsync(new IdentityRole<Guid> { Name = adminRole });
            }

            // Check if admin user exists
            var adminUser = await userManager.FindByEmailAsync(adminEmail);

            if (adminUser == null)
            {
                adminUser = new UserEntity
                {
                    UserName = "admin",
                    Email = adminEmail,
                    AccessGroup = "Administrator",
                    DateCreated = DateTime.UtcNow,
                    EmailConfirmed = true, // 🔹 Prevents email verification requirement
                    IsActive = true
                };

                var result = await userManager.CreateAsync(adminUser, adminPassword);

                if (result.Succeeded)
                {
                    await userManager.AddToRoleAsync(adminUser, adminRole);
                    Console.WriteLine("✅ Admin user created successfully!");
                }
                else
                {
                    Console.WriteLine("❌ Error creating admin user: " + string.Join(", ", result.Errors));
                }
            }
            else
            {
                Console.WriteLine("🔹 Admin user already exists.");
            }
        }
    }
}
